const $=id=>document.getElementById(id),L=Lab,D=DC;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let teams=[],selected=0,bans=[],builds={},busy=false,worker,baseline,generalBaseline,filters=[],excludedHeroes=[],pins=new Set(),baseIndex=null,baseSnapshot=null,ownBans=[],adviceEnabled=false,advice;
const options=(value,blank)=>`${blank?`<option value="">${blank}</option>`:''}${D.heroes.map(h=>`<option value="${h.id}" ${h.id===value?'selected':''}>${escape(h.localized_name)}</option>`).join('')}`;
const hero=id=>L.byId.get(id),image=id=>`<img class="portrait" src="${hero(id).img}" alt="${escape(hero(id).localized_name)}" loading="lazy">`;
const planName=p=>D.questions.map(q=>p[q.id]?(p[q.id]==='a'?q.optionA:q.optionB).name:'Unknown').join(' · ');
const enemy=()=>[...$('enemy').querySelectorAll('[data-enemy]')].map(s=>+s.value).filter(Boolean);
const locks=()=>Object.fromEntries([...$('locks').querySelectorAll('select')].filter(s=>s.value).map(s=>[s.dataset.role,+s.value]));
const analysisEnemy=()=>$('rankingMode').value==='current'?enemy():[];
const enemyPlan=()=>Object.fromEntries([...$('enemyChoices').querySelectorAll('select')].map(s=>[s.dataset.enemyChoice,s.value]).filter(([,v])=>v));
const enemyRoleOverrides=()=>Object.fromEntries([...$('enemy').querySelectorAll('[data-enemy]')].filter(s=>s.value&&s.parentElement.querySelector('[data-enemy-role]').value).map(s=>[s.value,s.parentElement.querySelector('[data-enemy-role]').value]));
function fillEnemyChoices(choices){$('enemyChoices').innerHTML=D.questions.map(q=>`<label>${escape(q.title)}<select data-enemy-choice="${q.id}"><option value="" ${!choices[q.id]?'selected':''}>Unknown / not revealed</option><option value="a" ${choices[q.id]==='a'?'selected':''}>${escape(q.optionA.name)}</option><option value="b" ${choices[q.id]==='b'?'selected':''}>${escape(q.optionB.name)}</option></select></label>`).join('')}

function setup(){
 $('enemy').innerHTML=Array.from({length:5},(_,i)=>`<label>Enemy pick ${i+1}<select data-enemy="${i}" aria-label="Enemy hero ${i+1}">${options(null,'Unknown / not picked')}</select><select data-enemy-role="${i}" aria-label="Enemy pick ${i+1} role"><option value="">Unknown · infer only for analysis</option>${L.roles.map(r=>`<option value="${r}">${L.names[r]}</option>`).join('')}</select></label>`).join('');
 $('locks').innerHTML=L.roles.map(r=>`<label>${L.names[r]}<select data-role="${r}"><option value="">Any eligible hero</option>${D.heroes.filter(h=>L.valid(h,r)).map(h=>`<option value="${h.id}">${escape(h.localized_name)}</option>`).join('')}</select></label>`).join('');
 $('enemyPlan').innerHTML=[['unknown','Unknown / not revealed'],['earlyAggro','Early aggression'],['lateScale','Late split'],['teamfightRosh','Teamfight / Rosh'],['custom','Custom axes']].map(([v,n])=>`<option value="${v}" ${v==='unknown'?'selected':''}>${n}</option>`).join('');
 fillEnemyChoices({});
 $('banPicker').innerHTML=options(null,'Choose a hero…');
 $('heroFilter').innerHTML=options(null,'Add hero filter…');
}
function back(){$('catalogue').hidden=false;$('detail').hidden=true;$('back').hidden=true}
function markChanged(){updateHeroAvailability();teams=[];baseIndex=null;baseSnapshot=null;pins.clear();back();$('teams').innerHTML='<tr><td colspan="12" class="empty">Matchup changed. Solve a new catalogue for these inputs.</td></tr>';$('detail').innerHTML='';$('teamCount').textContent='No calculated teams';$('rankingNote').textContent='No stale matchup results shown.';$('testTeams').disabled=true;$('comparisonBase').innerHTML='';$('comparePanel').innerHTML='';$('autoOptimize').disabled=true;refreshAdvice()}
function renderBans(){$('bans').innerHTML=bans.map(id=>`<button class="chip" data-remove="${id}" aria-label="Remove ban ${escape(hero(id).localized_name)}">${escape(hero(id).localized_name)} ×</button>`).join('')}
function duration(t){const wins=(t.overall?.opponents.flatMap(e=>e.tests)||t.benchmark?.tests||[]).filter(s=>s.win);return wins.length?wins.reduce((s,t)=>s+t.minute,0)/wins.length:Infinity}
function filtered(){const q=$('teamSearch').value.toLowerCase().trim();let rows=teams.map((t,i)=>({t,i})).filter(({t})=>filters.every(id=>t.ids.includes(id))&&!excludedHeroes.some(id=>t.ids.includes(id))&&(!q||`${t.ids.map(id=>hero(id).localized_name).join(' ')} ${t.fit.planLabel} ${planName(t.choices)}`.toLowerCase().includes(q)));const sort=$('sort').value;rows.sort((a,b)=>sort==='overall'?L.overallSort(a.t,b.t):sort==='solo'?(L.soloBenchmark(b.t.overall)?.rate??-1)-(L.soloBenchmark(a.t.overall)?.rate??-1)||L.overallSort(a.t,b.t):sort==='score'?b.t.score-a.t.score:sort==='match'?+(b.t.simulation?.win??-1)-+(a.t.simulation?.win??-1)||(b.t.simulation?.networthLead??-Infinity)-(a.t.simulation?.networthLead??-Infinity):sort==='nw'?((b.t.overall||b.t.benchmark)?.meanNetworthLead??-Infinity)-((a.t.overall||a.t.benchmark)?.meanNetworthLead??-Infinity):sort==='duration'?duration(a.t)-duration(b.t):((b.t.overall||b.t.benchmark)?.wins??-1)-((a.t.overall||a.t.benchmark)?.wins??-1)||((b.t.overall||b.t.benchmark)?.meanNetworthLead??-Infinity)-((a.t.overall||a.t.benchmark)?.meanNetworthLead??-Infinity)||b.t.score-a.t.score);return rows}
const color=id=>['#859dec','#cb6d7d','#84bfae','#c5b775','#ac87d6','#73adb8'][id%6];
function renderTeams(){
 L.rankConsistency(teams);
 const matchView=$('sort').value==='match',soloView=$('sort').value==='solo';$('suiteMetric').textContent=soloView?'Solo-weighted benchmark ↓':'Suite wins / tests ↓';$('suiteMetric').dataset.sort=soloView?'solo':'overall';const rows=filtered(),limit=$('rowLimit').value==='all'?Infinity:+$('rowLimit').value,base=baseSnapshot?.score;
 $('teamCount').textContent=`${rows.length} teams${rows.length===teams.length?'':` / ${teams.length} total`}`;
 $('teams').innerHTML=rows.slice(0,limit).map(({t,i},rank)=>`<tr class="${i===selected?'selected':''}"><td class="rank" title="${t.overall?.rankCheck?`Replication ranks: ${t.overall.rankCheck.first} and ${t.overall.rankCheck.second} among ${t.overall.rankCheck.candidates} tested candidates. Descriptive sensitivity, not a confidence interval.`:'No replication ranking available'}">${rank+1}${!soloView&&t.overall?.rankCheck?`<small style="display:block">${t.overall.rankCheck.min}–${t.overall.rankCheck.max}</small>`:''}</td>${t.ids.map((id,slot)=>`<td class="heroCell" style="--hero:${color(id)}"><button data-hero="${id}" data-team="${i}" data-role-slot="${slot}" title="${escape(`${hero(id).localized_name} · ${L.names[L.roles[slot]]}\n${(L.defaultBuilds(t.ids))[id].map(x=>D.items.find(i=>i.id===x)?.name||x).join(' → ')}`)}">${escape(hero(id).localized_name)}</button></td>`).join('')}<td><button class="score" data-select="${i}">${t.score.toFixed(1)}</button></td><td class="wins">${soloView?(L.soloBenchmark(t.overall)?`${(L.soloBenchmark(t.overall).rate*100).toFixed(1)}% weighted`:'—'):matchView?(t.simulation?`${t.simulation.win?'Win':'Loss'} / 1`:'—'):t.overall?`${t.overall.wins} / ${t.overall.total}`:t.benchmark?`${t.benchmark.wins} / ${t.benchmark.total}`:t.simulation?`${t.simulation.win?'Win':'Loss'} / 1`:'—'}</td><td class="nw">${matchView?(t.simulation?nw(t.simulation.networthLead):'—'):t.overall?nw(t.overall.meanNetworthLead):t.benchmark?nw(t.benchmark.meanNetworthLead):t.simulation?nw(t.simulation.networthLead):'—'}</td><td class="relative">${base===undefined?'—':`${t.score-base>=0?'+':''}${(t.score-base).toFixed(1)}`}</td><td><button class="rowbtn" data-select="${i}">config / counters ›</button></td><td><input type="checkbox" data-pin="${i}" aria-label="Pin team ${rank+1} for comparison" ${pins.has(i)?'checked':''}></td></tr>`).join('')||'<tr><td colspan="12" class="empty">No compositions match these filters.</td></tr>';
 $('testTeams').disabled=$('autoOptimize').disabled=busy||!rows.length;$('showMore').hidden=rows.length<=limit;$('optimizationHint').textContent=`Benchmarks use hypothetical opponents and both sides. Evaluate ${$('optCount').value==='all'?'all filtered teams':`the first ${$('optCount').value} in the current order`} with ${$('sampleSize').value} opponent profiles each. Auto optimize screens 64 strategies, refines a shortlist on training scenarios, then evaluates the chosen plan separately. Larger batches can take several minutes or longer; Cancel stops without applying partial results.`;
 $('comparisonBase').innerHTML='<option value="">None · choose a reference explicitly</option>'+rows.map(({t,i},rank)=>`<option value="${i}" ${i===baseIndex?'selected':''}>#${rank+1} · ${t.score.toFixed(1)} · ${escape(t.ids.map(id=>hero(id).localized_name).join(' / '))}</option>`).join('');if(baseSnapshot){if(!rows.some(r=>r.i===baseIndex))$('comparisonBase').insertAdjacentHTML('beforeend',`<option value="${baseIndex}" selected>Selected reference · outside current filters</option>`);$('baselineNote').textContent=`Saved reference: ${baseSnapshot.ids.map(id=>hero(id).localized_name).join(' / ')} · ${baseSnapshot.score.toFixed(1)} points. Δ uses this saved configuration.`}else $('baselineNote').textContent='No reference selected. List order follows the ranking and filters.';
 $('heroFilters').innerHTML=[...filters.map(id=>`<button class="chip" data-unfilter="${id}">Include ${escape(hero(id).localized_name)} ×</button>`),...excludedHeroes.map(id=>`<button class="chip" data-unexclude="${id}">Hide ${escape(hero(id).localized_name)} ×</button>`)].join('');
 renderComparison();
}
function renderComparison(){const entries=[...pins].filter(i=>teams[i]);$('comparePanel').innerHTML=entries.length?`<section class="comparison"><h3>Pinned compositions · ${entries.length}/4 <button id="clearPins">Clear</button></h3><div class="compareCards">${entries.map(i=>{const t=teams[i];return `<article><button data-select="${i}" class="rowbtn">${escape(t.ids.map(id=>hero(id).localized_name).join(' / '))}</button><p>Native value <b>${t.score.toFixed(1)}</b> · ${t.overall?`${t.overall.wins}/${t.overall.total} general scenario wins · ${nw(t.overall.meanNetworthLead)} NW`:t.benchmark?`${t.benchmark.wins}/6 scenario wins · ${nw(t.benchmark.meanNetworthLead)} NW`:t.simulation?`${t.simulation.win?'Win':'Loss'} in selected matchup · ${nw(t.simulation.networthLead)} NW`:'Untested'}</p><small>${escape(planName(t.choices))}</small><p><button data-reference="${i}">Use as comparison baseline</button></p><p>Build budget: ${buildCost(t).toLocaleString()} gold</p></article>`}).join('')}</div></section>`:''}
function buildCost(t){return Object.values(L.defaultBuilds(t.ids)).flat().reduce((s,id)=>s+(D.items.find(i=>i.id===id)?.cost||0),0)}
function nw(n){return `${n>=0?'+':''}${(n/1000).toFixed(1)}k`}
function renderDetail(){
 const t=teams[selected];if(!t)return;
 const conflict=t.ids.some(id=>enemy().includes(id)),labels={roleLaneFit:'Role & lane fit',doctrineAlignment:'Strategy fit',compositionFit:'Team balance',threatCoverage:'Counter coverage',synergyPotential:'Hero synergy',timingFit:'Power timing',redundancyPenalty:'Overlap penalty',comfortInfluence:'Comfort bonus'};
 const cap=t.cap,components=t.components,max={roleLaneFit:24,doctrineAlignment:16,compositionFit:12,threatCoverage:18,synergyPotential:9,timingFit:8,redundancyPenalty:30,comfortInfluence:10};
 $('detail').innerHTML=`<div class="detailHeader"><div><p class="eyebrow">TEAM CONFIGURATION</p><h2>${escape(t.fit.planLabel)}</h2></div><button id="copy">Copy draft & configuration</button></div><section id="counterPanel"></section><div class="metrics">${Object.entries(components).map(([k,v])=>`<div>${escape(labels[k]||k)}<b>${v.toFixed(2)}</b><div class="bar"><span style="width:${Math.min(100,Math.abs(v)/max[k]*100)}%"></span></div></div>`).join('')}</div><div class="badges">${['disable','save','reach','siege','waveclear'].map(k=>`<span class="badge">${k==='disable'?'Lockdown':k==='reach'?'Catch':k} ${Math.round(cap[k]*100)}%</span>`).join('')}<span class="badge">Plan requirements met ${Math.round(t.fit.coherence*100)}%</span></div>${t.fit.warnings.length||t.fit.gaps.length?`<ul>${[...t.fit.warnings,...t.fit.gaps].map(w=>`<li>${escape(w.message)}</li>`).join('')}</ul>`:''}<div class="strategy">${D.questions.map(q=>`<label>${escape(q.title)}<select data-choice="${q.id}"><option value="a" ${t.choices[q.id]==='a'?'selected':''}>${escape(q.optionA.name)}</option><option value="b" ${t.choices[q.id]==='b'?'selected':''}>${escape(q.optionB.name)}</option></select></label>`).join('')}</div><h3 class="sectionTitle">Default preset loadouts & close hero alternatives</h3><p class="muted">DotaCaptain draft defaults for each assigned role, in their original item order. Hero replacements keep this strategy; score changes are estimates until tested.</p><div class="builds">${t.ids.map((id,slot)=>`<article class="build">${image(id)}<h3>${escape(hero(id).localized_name)}</h3><p>${L.names[L.roles[slot]]}</p><ol class="defaultItems">${builds[id].map(item=>`<li>${escape(D.items.find(x=>x.id===item)?.name||item)}</li>`).join('')}</ol><p>Close replacements</p>${(t.alternatives?.[slot]?.options||[]).map(a=>`<button class="alternative" data-alt="${a.id}" data-role-slot="${slot}">${escape(hero(a.id).localized_name)}<br><small>${a.delta>=0?'+':''}${a.delta.toFixed(1)} draft points · untested</small></button>`).join('')||'<span class="muted">Role locked</span>'}</article>`).join('')}</div><div class="actions"><button id="run" class="primary" style="width:auto">Simulate selected matchup</button><button id="plans">Test all 64 strategies</button><button id="autoStrategy">Auto optimize this configuration</button><button id="stress">Test configuration · 6 scenarios</button></div><p class="note">${conflict?'This team shares a hero with confirmed enemy picks. Choose a different lineup to simulate this matchup. ':''}Single-match simulation needs five enemy heroes, all six enemy strategy choices, your side, and assigned roles or permission to infer them. The six-scenario test needs only enemy heroes and roles; it tests both sides and three preset enemy plans. Inferred roles are assumptions; changing them can change the result. Testing all 64 changes only your six strategy choices; roles and default item presets remain fixed.</p><div id="simulation"></div>`;
 for(const id of ['run','plans','autoStrategy'])$(id).disabled=busy||conflict||!matchReady();$('stress').disabled=busy||conflict||!scenarioReady();renderCounters(t);if(t.shownResult==='benchmark'&&t.benchmark)showBenchmark(t.benchmark);else if(t.simulation)showSimulation(t.simulation);else if(t.benchmark)showBenchmark(t.benchmark);
}
function showBenchmark(b){$('simulation').innerHTML=`<div class="simulation"><h3>Scenario stress test · ${b.wins}/${b.total} wins</h3><div class="tableWrap"><table class="scenario"><thead><tr><th>Enemy plan</th><th>Your side</th><th>Result</th><th>Duration</th><th>NW lead</th></tr></thead><tbody>${b.tests.map(s=>`<tr><td>${s.name}</td><td>${s.side}</td><td>${s.win?'Win':'Loss'}</td><td>${s.minute.toFixed(1)}m</td><td>${nw(s.networthLead)}</td></tr>`).join('')}</tbody></table></div></div>`}
function showSimulation(s){$('simulation').innerHTML=`<div class="simulation"><div class="outcome ${s.win?'':'loss'}">${s.win?'WIN':'LOSS'} · ${s.minute.toFixed(1)} minutes</div><p>${s.kills[0]}–${s.kills[1]} kills · ${nw(s.networthLead)} final net worth lead · ${escape(s.end.replaceAll('_',' '))}</p><p class="muted">One deterministic client result, not a predicted win rate. Draft brief fit ${Math.round(s.brief.draftBriefFit*100)}% · strategy coherence ${Math.round(s.brief.coherence*100)}%.</p><ul>${s.items.map(x=>`<li>${escape(hero(x.id).localized_name)}: ${x.completed.map(id=>escape(D.items.find(i=>i.id===id)?.name||id)).join(' → ')||'No completed build items'}</li>`).join('')}</ul></div>`}
function select(i){selected=i;Object.assign(teams[i],L.score(teams[i].ids,teams[i].choices,analysisEnemy()));builds=structuredClone(L.defaultBuilds(teams[i].ids));teams[i].alternatives=L.alternatives(teams[i],analysisEnemy(),bans,locks());renderTeams();renderDetail();$('catalogue').hidden=true;$('detail').hidden=false;$('back').hidden=false;window.scrollTo({top:0,behavior:'instant'})}
function setBusy(v){busy=v;document.querySelectorAll('button,select,input').forEach(e=>e.disabled=v);if(!v){updateKnowledge();$('status').textContent=''}}
function calculate(action,args){
 return new Promise((resolve,reject)=>{setBusy(true);$('status').innerHTML='Calculating… <button id="cancel">Cancel</button>';$('cancel').disabled=false;worker=new Worker('worker.js');let ended=false;
 const finish=(error,result)=>{if(ended)return;ended=true;worker.terminate();setBusy(false);error?reject(Error(error)):resolve(result)};
 $('cancel').onclick=()=>finish('Calculation cancelled.');
 worker.onmessage=({data})=>{if(data.progress){$('status').firstChild.textContent=data.progress+' ';return}finish(data.error,data.result)};
 worker.onerror=()=>finish('Calculation failed. Please reload the calculator.');worker.postMessage({action,args});
 });
}
function error(e){$('status').textContent=e.message;setTimeout(()=>{if(!busy)$('status').textContent=''},6000)}
async function search(){try{const e=$('rankingMode').value==='current'?enemy():[];if(new Set(e).size!==e.length)throw Error('Enemy picks must be different.');const ctx=generalContext();teams=await calculate('generalSearch',{enemy:ctx.enemy||[],bans,locks:locks(),context:ctx});$('sort').value='score';pins.clear();baseIndex=null;baseSnapshot=null;$('rankingNote').textContent='New candidate shortlist · sorted by native draft value · not match-tested yet. Benchmark or auto optimize a selected batch to compare simulation results.';back();renderTeams()}catch(e){error(e)}}
async function reset(){try{if(!baseline){const r=await fetch('baseline.json');if(!r.ok)throw Error('Could not load example.');baseline=await r.json()}bans=[];ownBans=[];filters=[];excludedHeroes=[];pins.clear();baseIndex=null;baseSnapshot=null;setup();$('matchType').value='scenario';$('rankingMode').value='current';document.querySelectorAll('[data-enemy]').forEach((s,i)=>s.value=String(L.enemyIds[i]));$('enemyPlan').value='lateScale';fillEnemyChoices(D.presets.lateScale);$('side').value='radiant';$('allowRoles').checked=true;teams=structuredClone(baseline.teams);$('sort').value='benchmark';$('rankingNote').textContent='EXAMPLE ONLY · five hypothetical enemy heroes · 6 scenarios per team';renderBans();back();setView('teams');renderTeams();updateKnowledge()}catch(e){error(e)}}
setup();
function refreshAdvice(){
 if(!adviceEnabled)return;const step=currentTurn();if(!step||!$('side').value||!$('opener').value){$('draftAdvice').hidden=false;$('draftAdvice').textContent='Enter the lottery side, first-pick side and current CM turn to recommend the actual action.';return}if(step.team!==$('side').value){$('draftAdvice').hidden=false;$('draftAdvice').textContent='Opponent turn: record their confirmed pick or ban, then select the next turn. Future picks remain unknown.';return}
 try{
  advice=L.draftAdvice({enemy:enemy(),enemyRoles:enemyRoleOverrides(),locks:locks(),bans,ownBans,choices:D.presets[$('draftPlan').value],enemyChoices:enemyPlan(),personality:$('enemyPersonality').value,action:step.action,stepIndex:+$('cmTurn').value,draftSequence:sequence(),playerTeam:$('side').value});
  $('draftAdvice').hidden=false;
  $('draftAdvice').innerHTML=`<div class="toolbar"><div><h2>Next ${escape(advice.action)} · ${advice.rows.length} candidates</h2><p class="muted">${advice.targetRole?`Native target: ${L.names[advice.targetRole]}. `:''}Confirmed: ${Object.entries(locks()).filter(([,id])=>id).map(([r,id])=>escape(hero(id).localized_name)+' ('+L.names[r]+')').join(' / ')||'None'}. ${advice.rivalPick?`Scenario-only opponent candidate: ${escape(hero(advice.rivalPick).localized_name)}. `:''}Original AI values on confirmed picks. Future enemy picks are unknown; no reply is shown without a complete explicit scout/scenario plan and known style.</p></div></div>${advice.complete?`<p>${advice.action==='pick'?'Your five roles are filled. Complete the enemy lineup to optimize configurations.':'The enemy lineup is complete; there are no future enemy picks to ban.'}</p>`:`<div class="tableWrap adviceTable"><table><thead><tr><th>#</th><th>Hero</th><th>Native ${advice.action} value</th><th>Role</th><th>Enemy pick value</th><th></th></tr></thead><tbody>${advice.rows.map((r,i)=>`<tr><td>${i+1}</td><td style="color:${color(r.id)}">${escape(hero(r.id).localized_name)}</td><td title="${escape(Object.entries(r.components||{}).map(([k,v])=>`${k}: ${v.toFixed(2)}`).join('\n'))}">${r.score.toFixed(2)}</td><td>${r.role?L.names[r.role]:'—'}</td><td>${r.rivalValue===undefined?'—':r.rivalValue.toFixed(2)}</td><td><button data-draft-apply="${i}">Confirm ${advice.action}</button></td></tr>`).join('')}</tbody></table></div><p class="note">${advice.action==='pick'?'Ranking excludes heroes outside an unfilled preferred role. Hover a native value for its original components.':'Ban value uses your confirmed picks, plan and earlier bans. Enemy pick value is a separate read using their plan and captain style.'} Confirm records the action here; it does not submit to DotaCaptain.</p>`}`;
 }catch(e){$('draftAdvice').hidden=false;$('draftAdvice').textContent=e.message;advice=null}
}
$('recommend').onclick=()=>{adviceEnabled=true;refreshAdvice()};
for(const id of ['draftAction','draftPlan','enemyPersonality','cmTurn','opener'])$(id).onchange=()=>{updateKnowledge();refreshAdvice()};
$('draftAdvice').onclick=e=>{const b=e.target.closest('[data-draft-apply]');if(!b||busy)return;const r=advice.rows[+b.dataset.draftApply];if(advice.action==='pick')document.querySelector(`#locks [data-role="${r.role}"]`).value=String(r.id);else{bans.push(r.id);ownBans.push(r.id);renderBans()}advanceTurn();markChanged()};
$('emptyDraft').onclick=()=>{$('matchType').value='solo';bans=[];ownBans=[];renderBans();document.querySelectorAll('#enemy select,#locks select').forEach(s=>s.value='');$('enemyPlan').value='unknown';fillEnemyChoices({});$('enemyPersonality').value='';$('side').value='';$('opener').value='';$('cmTurn').value='';$('allowRoles').checked=false;adviceEnabled=false;markChanged();$('draftAdvice').textContent='Empty draft. Enter the lottery results and current turn, then request recommendations.';updateKnowledge()};
function matchupConfigChanged(){if($('rankingMode').value==='current')for(const t of teams){delete t.overall;delete t.counters}for(const t of teams){delete t.simulation;delete t.benchmark;delete t.optimization;delete t.shownResult}window.planResults=null;updateKnowledge();$('rankingNote').textContent=$('rankingMode').value==='overall'?'General benchmarks use hypothetical opponents; changing live enemy information clears only the selected-match results.':'Current-draft inputs changed. Re-test the benchmark or selected matchup.';refreshAdvice()}
$('enemyPlan').onchange=()=>{if($('enemyPlan').value!=='custom')fillEnemyChoices(D.presets[$('enemyPlan').value]||{});matchupConfigChanged()};$('enemyChoices').onchange=()=>{$('enemyPlan').value='custom';matchupConfigChanged()};$('side').onchange=matchupConfigChanged;
$('autoOptimize').onclick=async()=>{try{const rows=filtered(),count=$('optCount').value==='all'?rows.length:+$('optCount').value,chosen=rows.slice(0,count);if(!chosen.length)throw Error('No teams match the filters.');const results=await calculate('generalOptimize',{teams:chosen.map(r=>({...r.t,originalIndex:r.i})),context:generalContext()});for(const t of results)teams[t.originalIndex]=t;selected=results[0].originalIndex;$('sort').value='overall';back();renderTeams();$('rankingNote').textContent=`Optimized ${results.length} teams · 64-plan screening, shortlist refinement on training scenarios; ranking uses separate evaluation scenarios`; }catch(e){error(e)}};
$('search').onclick=search;$('baseline').onclick=reset;
$('banPicker').onchange=e=>{if(e.target.value&&!bans.includes(+e.target.value)){bans.push(+e.target.value);if($('banOwner').value==='own')ownBans.push(+e.target.value);renderBans();markChanged()}e.target.value=''};
$('bans').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){bans=bans.filter(id=>id!==+b.dataset.remove);ownBans=ownBans.filter(id=>id!==+b.dataset.remove);renderBans();markChanged()}};
$('enemy').onchange=e=>{if($('rankingMode').value==='current'&&e.target.hasAttribute('data-enemy')){markChanged();updateKnowledge()}else matchupConfigChanged()};$('locks').onchange=()=>{markChanged();updateKnowledge()};
$('teams').onclick=e=>{const b=e.target.closest('[data-select]');if(b&&!busy)select(+b.dataset.select);const h=e.target.closest('[data-hero]');if(h&&!busy)heroMenu(h)};
$('teams').onchange=e=>{if(e.target.dataset.pin){const i=+e.target.dataset.pin;if(e.target.checked&&pins.size>=4){e.target.checked=false;error(Error('Pin up to four compositions.'));return}e.target.checked?pins.add(i):pins.delete(i);renderComparison()}};
$('testTeams').onclick=async()=>{try{const rows=filtered(),count=$('optCount').value==='all'?rows.length:+$('optCount').value,chosen=rows.slice(0,count);if(!chosen.length)throw Error('No teams match the filters.');const result=await calculate('generalTest',{teams:chosen.map(r=>({...r.t,originalIndex:r.i})),context:generalContext()});for(const t of result)teams[t.originalIndex]=t;$('sort').value='overall';$('rankingNote').textContent=`Benchmarked ${result.length} teams · fixed displayed plans · both sides. Other rows retain their own test counts or remain untested.`;renderTeams()}catch(e){error(e)}};
$('teamSearch').oninput=renderTeams;$('sort').onchange=renderTeams;$('rowLimit').onchange=renderTeams;$('comparisonBase').onchange=e=>{baseIndex=e.target.value===''?null:+e.target.value;baseSnapshot=baseIndex===null?null:structuredClone(teams[baseIndex]);renderTeams()};$('heroFilter').onchange=e=>{if(e.target.value&&!filters.includes(+e.target.value))filters.push(+e.target.value);e.target.value='';renderTeams()};$('heroFilters').onclick=e=>{if(e.target.dataset.unfilter)filters=filters.filter(id=>id!==+e.target.dataset.unfilter);if(e.target.dataset.unexclude)excludedHeroes=excludedHeroes.filter(id=>id!==+e.target.dataset.unexclude);renderTeams()};$('showMore').onclick=()=>{$('rowLimit').value=$('rowLimit').value==='50'?'100':'all';renderTeams()};$('back').onclick=back;$('ranking').querySelector('thead').onclick=e=>{if(e.target.dataset.sort){$('sort').value=e.target.dataset.sort;renderTeams()}};$('comparePanel').onclick=e=>{if(e.target.dataset.reference!==undefined){baseIndex=+e.target.dataset.reference;baseSnapshot=structuredClone(teams[baseIndex]);renderTeams()}if(e.target.id==='clearPins'){pins.clear();renderTeams()}if(e.target.dataset.select)select(+e.target.dataset.select)};
function heroMenu(button){document.getElementById('heroMenu')?.remove();const id=+button.dataset.hero,i=+button.dataset.team,slot=+button.dataset.roleSlot;const menu=document.createElement('div');menu.id='heroMenu';menu.className='heroMenu';menu.innerHTML=`<strong>${escape(hero(id).localized_name)}</strong><button data-show>Show ${escape(hero(id).localized_name)} teams</button><button data-hide>Hide ${escape(hero(id).localized_name)} teams</button><button data-config>View ${escape(hero(id).localized_name)} default loadout & alternatives</button><button data-plan>Compare this team's strategies</button><button data-close>Close ×</button>`;document.body.append(menu);const r=button.getBoundingClientRect();menu.style.left=Math.min(r.left,window.innerWidth-300)+'px';menu.style.top=Math.min(r.bottom,window.innerHeight-260)+'px';menu.onclick=e=>{if(e.target.hasAttribute('data-show')){if(!filters.includes(id))filters.push(id);excludedHeroes=excludedHeroes.filter(x=>x!==id);renderTeams()}if(e.target.hasAttribute('data-hide')){if(!excludedHeroes.includes(id))excludedHeroes.push(id);filters=filters.filter(x=>x!==id);renderTeams()}if(e.target.hasAttribute('data-config')){select(i);document.querySelectorAll('.build')[slot].scrollIntoView({block:'center'})}if(e.target.hasAttribute('data-plan')){select(i);$('plans').click()}menu.remove()}}
$('detail').onchange=e=>{
 if(e.target.dataset.choice){const t=teams[selected];t.choices={...t.choices,[e.target.dataset.choice]:e.target.value};Object.assign(t,L.score(t.ids,t.choices,analysisEnemy()));t.alternatives=L.alternatives(t,analysisEnemy(),bans,locks());delete t.benchmark;delete t.overall;delete t.counters;delete t.generalOptimization;delete t.simulation;delete t.optimization;window.planResults=null;renderTeams();renderDetail();$('rankingNote').textContent='Strategy changed. Re-test to update scenario ranking.'}
};
$('detail').onclick=async e=>{const b=e.target.closest('button');if(!b||busy)return;try{
 if(b.dataset.alt){const t=teams[selected],ids=[...t.ids];ids[+b.dataset.roleSlot]=+b.dataset.alt;const replacement={ids,choices:{...t.choices},...L.score(ids,t.choices,analysisEnemy())};replacement.alternatives=L.alternatives(replacement,analysisEnemy(),bans,locks());teams[selected]=replacement;select(selected);$('rankingNote').textContent='Replacement applied. Re-test to update results.'}
 else if(b.id==='counterScan'){const r=await calculate('counters',{team:teams[selected],context:{bans}});teams[selected].counters=r;renderCounters(teams[selected]);$('counterPanel').scrollIntoView({block:'start'})}
 else if(b.id==='generalStrategy'){const r=await calculate('generalOptimize',{teams:[{...teams[selected],originalIndex:selected}],context:generalContext()});teams[selected]=r[0];select(selected)}
 else if(b.dataset.counterBan){const id=+b.dataset.counterBan;if(enemy().includes(id)||Object.values(locks()).includes(id)||teams[selected].ids.includes(id))throw Error('A confirmed or chosen hero cannot be banned.');if(!bans.includes(id)){bans.push(id);ownBans.push(id)}renderBans();for(const t of teams){delete t.overall;delete t.counters;delete t.simulation;delete t.benchmark;delete t.optimization;delete t.generalOptimization}renderTeams();renderDetail();$('rankingNote').textContent='Ban added · suite results cleared. Re-test or search counters again to evaluate replacements.'}
 else if(b.id==='run'){const s=await calculate('run',{team:teams[selected],enemy:enemy(),enemyRoles:enemyRoleOverrides(),enemyChoices:enemyPlan(),side:$('side').value});teams[selected].simulation=s;teams[selected].shownResult='simulation';renderTeams();showSimulation(s)}
 else if(b.id==='stress'){const result=await calculate('benchmark',{teams:[teams[selected]],enemy:enemy(),enemyRoles:enemyRoleOverrides()});teams[selected]={...result[0],shownResult:'benchmark'};renderTeams();showBenchmark(result[0].benchmark)}
 else if(b.id==='autoStrategy'){const results=await calculate('optimize',{teams:[{...teams[selected],originalIndex:selected}],enemy:enemy(),enemyRoles:enemyRoleOverrides(),enemyChoices:enemyPlan(),side:$('side').value});teams[selected]=results[0];select(selected);$('rankingNote').textContent='Best of all 64 strategies for this lineup and selected matchup.'}
 else if(b.id==='plans'){const results=await calculate('plans',{team:teams[selected],enemy:enemy(),enemyRoles:enemyRoleOverrides(),enemyChoices:enemyPlan(),side:$('side').value});$('simulation').innerHTML=`<div class="simulation"><h3>All 64 strategies tested · ${results.filter(r=>r.simulation.win).length} winning configurations</h3><p class="muted">Sorted by win, then final NW lead in this single matchup. Apply a strategy, then stress-test both sides to check robustness.</p><div class="tableWrap"><table class="scenario"><thead><tr><th>Strategy</th><th>Result</th><th>NW lead</th><th></th></tr></thead><tbody>${results.map((r,i)=>`<tr><td>${escape(planName(r.choices))}</td><td>${r.simulation.win?'Win':'Loss'}</td><td>${nw(r.simulation.networthLead)}</td><td><button data-apply="${i}">Apply</button></td></tr>`).join('')}</tbody></table></div></div>`;window.planResults=results}
 else if(b.dataset.apply){const r=window.planResults[+b.dataset.apply];delete r.benchmark;delete r.overall;delete r.counters;Object.assign(r,L.score(r.ids,r.choices,analysisEnemy()));teams[selected]={...r,alternatives:L.alternatives(r,analysisEnemy(),bans,locks())};renderTeams();renderDetail();showSimulation(r.simulation);$('rankingNote').textContent='Simulation-selected strategy applied · re-test scenarios to update ranking';window.planResults=null}
 else if(b.id==='copy'){const t=teams[selected],text=`Dota Captain Lab — snapshot 2026-10-06\nEnemy: ${enemy().map(id=>hero(id).localized_name).join(', ')}\nYour side: ${$('side').value}\n${t.ids.map((id,i)=>`${L.names[L.roles[i]]}: ${hero(id).localized_name}\n  ${builds[id].map(x=>D.items.find(i=>i.id===x)?.name||x).join(' → ')}`).join('\n')}\nStrategy: ${planName(t.choices)}\nEnemy strategy: ${planName(enemyPlan())}\nMean native AI draft value: ${t.score.toFixed(2)}; not an official team score or win probability.\n${t.overall?`General suite wins: ${t.overall.wins}/${t.overall.total}; ${t.overall.scope}; not real-match probability.`:t.benchmark?`Scenario wins: ${t.benchmark.wins}/${t.benchmark.total}.`:'Configuration not scenario-tested.'}\n${(t.counters?.teams||L.strongest(t.overall?.opponents||[])).map((e,i)=>`Hypothetical counter ${i+1}: ${e.ids.map(id=>hero(id).localized_name).join(' / ')}; ${e.wins}/${e.total} opponent scenario wins; ${planName(e.choices)}`).join('\n')}`;await navigator.clipboard.writeText(text);$('status').textContent='Draft and configuration copied.';setTimeout(()=>$('status').textContent='',2500)}
}catch(e){error(e)}};
$('teams').innerHTML='<tr><td colspan="12" class="empty">Loading the pre-tested general rankings… You can also find an untested candidate shortlist for your current constraints.</td></tr>';
const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'search_drafts',description:'Find up to 120 role-valid candidate DotaCaptain drafts using native AI values; benchmark testing is a separate explicit action and update the visible table. Does not play matches or change your DotaCaptain account.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input)=>{if(input&&Object.keys(input).length)throw Error("This tool accepts no arguments.");await search();return{teams:teams.map(t=>({heroes:t.ids.map(id=>hero(id).localized_name),nativeDraftValue:t.score,choices:t.choices}))}}})).catch(()=>{})}catch{}}

function sequence(){return DC.flow.sequence.map(s=>({...s,team:$('opener').value==='dire'?(s.team==='radiant'?'dire':'radiant'):s.team}))}
function currentTurn(){return $('cmTurn').value===''?null:sequence()[+$('cmTurn').value]}
function advanceTurn(){const n=+$('cmTurn').value+1;$('cmTurn').value=n<24?String(n):'';updateKnowledge()}
function updateHeroAvailability(){const own=Object.values(locks()),opponents=enemy();for(const el of document.querySelectorAll('[data-enemy],#locks select,#banPicker')){const current=+el.value,unavailable=new Set([...bans,...own,...opponents]);for(const option of el.options){const id=+option.value;option.disabled=!!id&&id!==current&&unavailable.has(id)}}}
function scenarioReady(){const r=Object.values(enemyRoleOverrides());return enemy().length===5&&new Set(enemy()).size===5&&new Set(r).size===r.length&&(r.length===5||$('allowRoles').checked)}
function matchReady(){return scenarioReady()&&D.questions.every(q=>enemyPlan()[q.id])&&!!$('side').value}
function updateKnowledge(){updateHeroAvailability();const pvp=$('matchType').value==='pvp';$('enemyPersonality').disabled=pvp||busy;$('enemyPlan').disabled=pvp||busy;document.querySelectorAll('[data-enemy-choice]').forEach(e=>e.disabled=pvp||busy);if(pvp){$('enemyPersonality').value='';$('enemyPlan').value='unknown';fillEnemyChoices({});document.querySelectorAll('[data-enemy-choice]').forEach(e=>e.disabled=true)}sequence().forEach((s,i)=>{$('cmTurn').options[i+1].textContent=`${i+1} · ${$('opener').value?s.team+' ':''}${s.action}${$('side').value&&$('opener').value?' · '+(s.team===$('side').value?'you':'opponent'):''}`});const turn=currentTurn();if(turn)$('draftAction').value=turn.action;$('turnHint').textContent=turn&&$('opener').value?`Turn ${+$('cmTurn').value+1}/24 · ${turn.team} ${turn.action}${$('side').value?turn.team===$('side').value?' · your action':' · opponent action':''}. Select the next turn after every confirmed action, including skipped bans.`:'Use the actual CM turn; counts alone cannot account for skipped bans.';$('knowledgeNote').textContent=`${enemy().length}/5 revealed picks. ${Object.keys(enemyRoleOverrides()).length}/5 roles assigned for analysis. ${Object.keys(enemyPlan()).length}/6 explicit plan axes. ${pvp?'PvP strategy and final enemy roles are hidden before simulation. Switch to Hypothetical scenario to test assumptions.':'Solo scout describes doctrine and style, not future picks or guaranteed final roles.'} ${$('allowRoles').checked?'Simulation will infer missing roles; these are not observed facts.':'Simulation waits for assigned roles or explicit permission to infer.'}`;renderTeams();if(!$('detail').hidden)renderDetail()}
function setView(view){if(view==='teams')restoreGeneralReference();if(view==='draft'){draftInputs.append($('opponentControls'));$('cmTurn').closest('label').before(sideLabel)}else{$('opponentHome').after($('opponentControls'));$('allowRoles').closest('label').before(sideLabel)}document.body.dataset.view=view;$('draftTab').setAttribute('aria-pressed',view==='draft');$('teamsTab').setAttribute('aria-pressed',view==='teams');back()}
$('draftTab').onclick=()=>setView('draft');$('teamsTab').onclick=()=>setView('teams');$('recommend').addEventListener('click',()=>{setView('draft');$('draftAdvice').scrollIntoView({block:'start',behavior:'smooth'})});$('search').addEventListener('click',()=>setView('teams'));
$('matchType').onchange=()=>{matchupConfigChanged()};$('allowRoles').onchange=matchupConfigChanged;
$('optCount').closest('.toolbar').insertAdjacentHTML('afterend','<p id="optimizationHint" class="note"></p>');$('comparisonBase').insertAdjacentHTML('afterend','<p id="baselineNote" class="note"></p>');
$('cmTurn').innerHTML+=DC.flow.sequence.map((s,i)=>`<option value="${i}">${i+1} · ${s.action}</option>`).join('');
const opponentHome=document.createElement('span');opponentHome.id='opponentHome';$('opponentControls').before(opponentHome);const draftInputs=document.createElement('div');draftInputs.id='draftInputs';$('draftAdvice').after(draftInputs);draftInputs.append($('draftControls'),$('pickControls'));const sideLabel=$('side').closest('label');$('cmTurn').closest('label').before(sideLabel,$('opener').closest('label')); setView('draft');updateKnowledge();

function generalContext(){const profiles=+$('sampleSize').value;return $('rankingMode').value==='overall'?{bans:[...bans],profiles}:{bans:[...bans],profiles,enemy:enemy(),enemyRoles:enemyRoleOverrides(),enemyChoices:enemyPlan()}}
function renderCounters(t){
 const threats=t.counters?.teams||L.strongest(t.overall?.opponents||[]),priority=L.banTargets(t,threats),solo=L.soloBenchmark(t.overall);
 $('counterPanel').innerHTML=`<div class="generalSummary"><p><b>Against:</b> ${escape(t.ids.map(id=>hero(id).localized_name).join(' / '))}</p><h3>${t.overall?`Overall test suite · ${t.overall.wins}/${t.overall.total} wins`:'General test suite · not tested'}</h3>${t.overall?`<p>${nw(t.overall.meanNetworthLead)} mean NW lead · ${t.overall.opponents.length} weighted scenario profiles · ${t.overall.uniqueMatches??t.overall.total} unique side-specific cases · both sides · fixed displayed configuration.</p><div class="chips">${t.overall.groups.map(g=>`<span class="badge">${escape({earlyAggro:'Early aggression',lateScale:'Late split',teamfightRosh:'Teamfight / Rosh'}[g.label]||g.label)} ${g.wins}/${g.total}</span>`).join('')}</div><p class="note">${t.overall.batches?`Replication results: ${t.overall.batches.map(g=>`${g.wins}/${g.total}`).join(' vs ')}. ${t.overall.rankCheck?`Unweighted replication ranks ${t.overall.rankCheck.positions.join(', ')} among ${t.overall.rankCheck.candidates} evaluated candidates.`:""}`:""} These show sensitivity to generated scenarios, not real win odds. Equal policy weights are a benchmark assumption; unknown roles vary over preferred-role assignments.</p>${t.generalOptimization?`<p class="note">Optimization: 64 plans screened; ${t.generalOptimization.finalists} refined on 128 training profiles. Training ${t.generalOptimization.trainingWins}/${t.generalOptimization.trainingTotal}; separate evaluation ${t.overall.wins}/${t.overall.total}. ${t.generalOptimization.overlappingProfiles} evaluation profiles also occur in training; fully revealed inputs can leave no independent scenario variation. Evaluation results do not choose the plan. Repeated manual optimization can still overfit this fixed benchmark.</p>`:""}`:''}${solo?`<p class="note"><b>Solo-doctrine weighted benchmark: ${(solo.rate*100).toFixed(1)}%</b> · weights follow the public solo strategy generator. Assumes uniform seed randomness; opponent heroes still use our two hypothetical policies. This is not a measured chance to win Solo matches.</p>`:''}<button id="generalStrategy">Auto optimize · separate evaluation</button></div><h3>Three strongest ${t.counters?'counter lineups found':'opponent lineups in the suite'}</h3><p class="note">${t.counters?`Screened ${t.counters.screened} lineups across three plans, then searched all 64 plans for ${t.counters.exhaustiveLineups} shortlisted lineups.`:'The suite gives an initial counter read. Search stronger counters to explore targeted lineups and all 64 plans for the shortlist.'} Your displayed plan stays fixed. Counter search explores hypothetical opponents and excludes recorded bans; it does not predict the current enemy. Wins are deterministic test results, not real-match odds or a guarantee that these are the best possible counters.</p>${threats.length?`<div class="counterCards">${threats.map((e,i)=>`<article><h4>#${i+1} · Opponent wins ${e.wins}/${e.total}</h4><p>${e.ids.map((id,n)=>`${L.names[L.roles[n]]}: <b>${escape(hero(id).localized_name)}</b>`).join('<br>')}</p><p>${escape(planName(e.choices))}</p><small>${nw(e.meanNetworthLead)} mean opponent NW lead${e.strategies?' · 64 counter plans searched':' · screened plan'}</small></article>`).join('')}</div><h4>Ban priorities · break the found lineups</h4><div class="chips">${priority.map(p=>`<button data-counter-ban="${p.id}" ${busy||enemy().includes(p.id)||Object.values(locks()).includes(p.id)?'disabled':''}>Ban ${escape(hero(p.id).localized_name)} · blocks ${p.blocks}/${threats.length}</button>`).join('')}</div><p class="note">Coverage is ranked first, then the native protection ban value. A ban prevents these exact lineups; the opponent can replace that hero. Confirmed picks cannot be banned.</p>`:'<p>No counter data for this configuration yet.</p>'}<button id="counterScan">Search stronger counters</button>`;
 for(const id of ['generalStrategy','counterScan'])$(id).disabled=busy;
}
$('rankingMode').onchange=()=>{markChanged();restoreGeneralReference();$('rankingNote').textContent=$('rankingMode').value==='overall'?'Overall scope: live enemy information is not assumed. Solve the general catalogue.':'Current scope: revealed enemy picks and scout axes constrain hypothetical completions. Solve a new catalogue.'};
fetch('general-baseline.json?v=stratified64v2').then(r=>{if(!r.ok)throw Error('General reference could not load.');return r.json()}).then(data=>{generalBaseline=data;if($('rankingMode').value==='overall'&&!busy&&!teams.length&&!bans.length&&!Object.values(locks()).length){teams=structuredClone(data.teams);$('sort').value='overall';$('rankingNote').textContent=`General reference · ${teams.length} candidate teams · 256 stratified profiles × both sides · all 64 enemy plans · two lineup policies · fixed screened plans${data.diagnostics?` · 128→256 profile top-10 agreement ${data.diagnostics.expansionTop10Overlap}/10`:""}`;renderTeams()}}).catch(error);

function restoreGeneralReference(){if(generalBaseline&&$('rankingMode').value==='overall'&&!teams.length&&!bans.length&&!Object.values(locks()).length&&!busy){teams=structuredClone(generalBaseline.teams);$('sort').value='overall';renderTeams()}}

$('optCount').onchange=renderTeams;
$('sampleSize').onchange=()=>{renderTeams();$('rankingNote').textContent='Sample size changed. Re-test the filtered teams to apply it; existing results keep their displayed denominators.'};
